"""Build a self-contained, offline HTML portfolio dashboard from synthetic outputs.

No network, CDN or third-party assets are needed. The output is viewable in a browser.
"""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
alerts = json.loads((ROOT/'outputs'/'incidents.json').read_text(encoding='utf-8'))
html = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>SentinelSOC | Hybrid SOC Detection Lab</title>
<style>
:root{--bg:#0b1325;--panel:#121f35;--panel2:#152640;--line:#2a3b55;--text:#f3f7fd;--muted:#9aacbd;--accent:#70bff7;--good:#4ad6b3;--danger:#ff8387;--orange:#ffbf69}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 ui-sans-serif,system-ui,-apple-system,Segoe UI,Arial,sans-serif}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}
.wrap{max-width:1300px;margin:auto;padding:0 28px}.top{position:sticky;top:0;z-index:10;background:#0b1325f2;border-bottom:1px solid var(--line);backdrop-filter:blur(12px)}.nav{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:14px 0}.brand{font-weight:800;letter-spacing:-.6px;font-size:20px}.brand span{color:var(--accent)}.links{display:flex;gap:24px;flex-wrap:wrap;font-size:13px}.eyebrow{text-transform:uppercase;letter-spacing:2.3px;color:var(--good);font-size:12px;font-weight:800}
.hero{padding:60px 0 34px;display:grid;grid-template-columns:1.7fr 1fr;gap:28px;align-items:center}.hero h1{font-size:clamp(34px,5vw,58px);letter-spacing:-2px;line-height:1.07;margin:14px 0}.hero p{color:var(--muted);font-size:17px;max-width:680px}.tiny{color:var(--muted);font-size:12px}.demo{display:inline-block;border:1px solid #4b725f;background:#163b37;color:#adfce2;border-radius:30px;padding:7px 13px;font-size:12px;font-weight:800}.hero-note{background:linear-gradient(135deg,#1b3150,#152139);border:1px solid #355170;padding:25px;border-radius:18px}.hero-note h3{font-size:18px;margin:0 0 14px}.hero-note p{font-size:14px;color:#d4dfea}.hero-note strong{color:#fff}
.section{padding:25px 0}.section h2{font-size:22px;letter-spacing:-.5px;margin:0 0 17px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.kpi{background:var(--panel);border:1px solid var(--line);padding:22px;border-radius:15px}.kpi .num{font-size:36px;line-height:1.1;font-weight:800;letter-spacing:-1px;margin-top:10px}.kpi label{font-size:12px;text-transform:uppercase;letter-spacing:.8px;color:var(--muted);font-weight:700}.kpi small{display:block;font-size:12px;color:var(--muted);margin-top:8px}
.grid{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(280px,1fr);gap:18px}.panel{background:var(--panel);border:1px solid var(--line);padding:23px;border-radius:16px;min-width:0}.panel h3{margin:0 0 18px;font-size:18px}.pill{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.7px;padding:4px 9px;border-radius:999px;white-space:nowrap;display:inline-block}.critical{background:#4e2633;color:#ffa2aa}.high{background:#543921;color:#ffd49b}.medium{background:#243f59;color:#95caff}.bar-label{display:flex;justify-content:space-between;margin-top:16px;color:#d9e4f0;font-size:13px}.bar-track{height:8px;background:#263752;border-radius:30px;overflow:hidden;margin-top:7px}.bar-fill{height:100%;background:#73bcf7;border-radius:30px}.bar-fill.c{background:#ff8894}.bar-fill.h{background:#ffbf69}.bar-fill.m{background:#81c5f3}
.controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:10px 0 20px}.filter{border:1px solid #37506c;color:#d8e8fb;background:#192a43;padding:9px 15px;border-radius:9px;cursor:pointer;font-size:12px;font-weight:700}.filter.active{background:#254d72;border-color:#64acdc;color:#fff}.filter:focus-visible,.incident:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.alert-list{display:flex;flex-direction:column;gap:10px}.incident{width:100%;display:grid;grid-template-columns:1fr auto;align-items:center;gap:18px;text-align:left;border-radius:12px;border:1px solid var(--line);background:#17283f;padding:16px 18px;color:var(--text);cursor:pointer}.incident:hover{border-color:#5b8eb5;background:#1e344f}.incident.selected{border-color:var(--accent);background:#1d3853}.incident h4{font-size:14px;margin:2px 0 6px}.incident .code{font-size:11px;color:var(--accent);letter-spacing:.6px;font-weight:800}.detail{border-top:1px solid var(--line);padding-top:16px;margin-top:10px;min-height:240px}.detail pre{padding:14px;background:#0d1b2f;border-radius:10px;border:1px solid #273e58;color:#d2e6f6;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.detail p{font-size:13px;color:#c3d3e2}
.step{display:flex;gap:14px;margin:18px 0}.dot{width:30px;height:30px;flex:0 0 30px;border-radius:50%;display:grid;place-items:center;background:#274967;border:1px solid #4e84aa;color:#c0e7fc;font-size:12px;font-weight:800}.step h4{margin:0;font-size:14px}.step p{color:var(--muted);font-size:12px;margin:5px 0}
.footer{border-top:1px solid var(--line);padding:24px 0 46px;color:var(--muted);font-size:12px}.caption{font-size:12px;color:var(--muted);margin-top:12px}.tag{border:1px solid #41607b;color:#a6d7fc;padding:6px 10px;border-radius:8px;display:inline-block;font-size:12px;margin:3px}.warning{padding:14px 18px;border-radius:12px;background:#2b2a27;border:1px solid #676042;color:#f9e7bd;font-size:13px;margin:25px 0 3px}
@media(max-width:920px){.hero,.grid{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,1fr)}}
@media(max-width:600px){.wrap{padding:0 16px}.links{gap:8px}.links a{font-size:11px}.hero{padding-top:38px}.hero h1{font-size:35px}.kpis{grid-template-columns:1fr 1fr}.kpi{padding:16px}.kpi .num{font-size:27px}}
</style>
</head>
<body>
<header class="top"><div class="wrap nav"><div class="brand">Sentinel<span>SOC</span> <span class="tiny">/ portfolio lab</span></div><nav class="links"><a href="#overview">Overview</a><a href="#incidents">Incidents</a><a href="#workflow">Workflow</a></nav></div></header>
<main class="wrap">
<section class="hero" id="overview"><div><span class="eyebrow">SOC L2 / security operations portfolio</span><h1>Detect. Correlate.<br/>Investigate.</h1><p>A hybrid SOC demonstration built around Microsoft Sentinel analytics, identity threats, Windows security telemetry, MITRE ATT&amp;CK and analyst-led incident response.</p><span class="demo">Synthetic data • Offline demo • No production access</span><p class="tiny">Prepared for Shaik Omer Ahmed · Personal portfolio · November 2026</p></div><aside class="hero-note"><h3>Lab investigation focus</h3><p><strong>Primary scenario:</strong> multi-account authentication failures followed by a successful login from the same IP.</p><p><strong>Supporting alerts:</strong> suspicious PowerShell execution and a security-enabled group membership change.</p><p><strong>Response approach:</strong> triage, evidence gathering, severity assessment and human-approved containment.</p></aside></section>
<div class="warning"><strong>Evidence notice:</strong> This page displays fictional lab records only. Counts are fixture results—not real employer KPIs, production alerts, MTTD/MTTR measurements, or an actual cloud deployment.</div>
<section class="section"><h2>Lab telemetry at a glance</h2><div class="kpis"><div class="kpi"><label>Sign-in events</label><div class="num">20</div><small>Synthetic identity log records</small></div><div class="kpi"><label>Windows events</label><div class="num">4</div><small>Synthetic endpoint and AD records</small></div><div class="kpi"><label>Candidate alerts</label><div class="num">4</div><small>Every alert needs validation</small></div><div class="kpi"><label>Automated tests</label><div class="num">6</div><small>Detection and negative controls pass</small></div></div></section>
<section class="section grid" id="incidents"><div class="panel"><h3>Detected scenarios</h3><div class="controls"><button class="filter active" data-filter="All">All alerts</button><button class="filter" data-filter="Critical">Critical</button><button class="filter" data-filter="High">High</button><button class="filter" data-filter="Medium">Medium</button></div><div class="alert-list" id="list"></div><p class="caption">Select a scenario for evidence and analyst recommendations.</p></div><div class="panel"><h3>Selected incident</h3><div id="details" class="detail" aria-live="polite"></div></div></section>
<section class="section grid"><div class="panel"><h3>Severity distribution</h3><div class="bar-label"><span>Critical</span><b>1</b></div><div class="bar-track"><div class="bar-fill c" style="width:25%"></div></div><div class="bar-label"><span>High</span><b>2</b></div><div class="bar-track"><div class="bar-fill h" style="width:50%"></div></div><div class="bar-label"><span>Medium</span><b>1</b></div><div class="bar-track"><div class="bar-fill m" style="width:25%"></div></div><p class="caption">Illustrative distribution for a small fixed fixture—not a security effectiveness metric.</p></div><div class="panel"><h3>Mapped ATT&amp;CK techniques</h3><div><span class="tag">T1110.003 • Password Spraying</span><span class="tag">T1078 • Valid Accounts</span><span class="tag">T1059.001 • PowerShell</span><span class="tag">T1098.007 • Group Membership</span></div><p class="caption">Technique association is a detection hypothesis; incident-level attribution requires additional evidence.</p></div></section>
<section class="section" id="workflow"><h2>SOC incident workflow</h2><div class="grid"><div class="panel"><div class="step"><span class="dot">01</span><div><h4>Collect and normalize telemetry</h4><p>Entra sign-ins, Windows Security Event IDs, identity and endpoint context.</p></div></div><div class="step"><span class="dot">02</span><div><h4>Apply KQL-aligned analytic logic</h4><p>Rule thresholds, multi-account correlation, risk indicators and negative controls.</p></div></div><div class="step"><span class="dot">03</span><div><h4>Prioritize and investigate</h4><p>Assign severity, correlate entities, validate maintenance and user context.</p></div></div><div class="step"><span class="dot">04</span><div><h4>Escalate with analyst approval</h4><p>Preserve evidence and request sign-off before disruptive containment.</p></div></div></div><div class="panel"><h3>Implementation boundaries</h3><p><strong>Working components:</strong> Python fixture generator, event correlation, candidate alert JSON, investigation report, automated unit tests, this interactive dashboard.</p><p><strong>Illustrative cloud components:</strong> KQL queries for native Sentinel tables and documented Azure Logic Apps response workflow.</p><p class="tiny">No cloud connectors, Defender policies or Logic App playbooks are deployed by this repository. No data is sent anywhere from this page.</p></div></div></section>
</main><footer class="footer"><div class="wrap">SentinelSOC portfolio demonstration • For SOC L2 interviews and personal learning • All records synthetic and safe to share.</div></footer>
<script>
const alerts = __ALERTS_JSON__;
const list = document.getElementById('list');
const details = document.getElementById('details');
let currentFilter = 'All'; let current = alerts[0]?.rule_id;
const escapeHTML = str => String(str).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){
  const visible = alerts.filter(a=>currentFilter==='All'||a.severity===currentFilter);
  if(!visible.find(a=>a.rule_id===current))current=visible[0]?.rule_id;
  list.innerHTML = visible.map(a=>`<button class="incident ${current===a.rule_id?'selected':''}" data-code="${escapeHTML(a.rule_id)}"><div><div class="code">${escapeHTML(a.rule_id)} • ${escapeHTML(a.mitre_technique)}</div><h4>${escapeHTML(a.title)}</h4><div class="tiny">${escapeHTML(a.observed_at_utc)}</div></div><span class="pill ${escapeHTML(a.severity.toLowerCase())}">${escapeHTML(a.severity)}</span></button>`).join('');
  for (const el of list.querySelectorAll('.incident')) el.addEventListener('click',()=>{current=el.dataset.code;render()});
  const selected = alerts.find(a=>a.rule_id===current);
  if(!selected){details.textContent='No alerts in this filter.';return}
  details.innerHTML=`<span class="pill ${escapeHTML(selected.severity.toLowerCase())}">${escapeHTML(selected.severity)}</span><h3>${escapeHTML(selected.title)}</h3><p><b>MITRE:</b> ${escapeHTML(selected.mitre_technique)}<br/><b>Timestamp:</b> ${escapeHTML(selected.observed_at_utc)}<br/><b>Status:</b> ${escapeHTML(selected.status)}</p><strong>Evidence (synthetic)</strong><pre>${escapeHTML(JSON.stringify(selected.evidence,null,2))}</pre><strong>Recommended investigation</strong><p>${escapeHTML(selected.analyst_next_step)}</p>`;
}
for(const btn of document.querySelectorAll('.filter'))btn.addEventListener('click',()=>{currentFilter=btn.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===btn));render()});
render();
</script>
</body></html>'''
html = html.replace('__ALERTS_JSON__', json.dumps(alerts, ensure_ascii=True).replace('</','<\\/'))
(ROOT/'dashboard'/'index.html').write_text(html, encoding='utf-8')
print(f'Wrote dashboard/index.html ({len(html):,} chars) with {len(alerts)} synthetic alerts')
